struct AdderFunctor {
    int offset;

    AdderFunctor(int o) : offset(o) {}

    // Overload the function call operator
    int operator()(int input) const {
        return input + offset;
    }
};

// Usage Example
AdderFunctor add_10(10);
int result = add_10(5); // result is 15
// Immediate use: AdderFunctor(20)(3); // result is 23
